-- TEST-HSA-04: TEST · HSA phần Khoa học
INSERT INTO exam.exam (id, code, code_normalized, name, description, instructions,
    kind_item_id, scope, part_code, subject_item_id, template_code, structure_year,
    matrix_year, years_confirmed, timing, duration_minutes, max_score, reference_max,
    practice_scoring, status, check_status, question_count, has_essay,
    has_english_option, combination_count, has_unpublished_changes, revision) VALUES
  ('3dccbbfd-7a19-5ac4-8e87-ed56b35f2c81','TEST-HSA-04','test-hsa-04','TEST · HSA phần Khoa học','Đề test giả định dựng từ mẫu HSA_PART_SCIENCE (UNI-2701).',NULL,'00000000-0000-7000-8200-000000000101','PART','SCIENCE',NULL,'HSA_PART_SCIENCE',2026,2026,true,'PER_PART',60,50,NULL,'RAW','DRAFT','UNCHECKED',50,false,false,0,false,0)
ON CONFLICT (id) DO NOTHING;

WITH upgrading AS (SELECT s.exam_id FROM exam.exam_structure s
    WHERE s.exam_id = '3dccbbfd-7a19-5ac4-8e87-ed56b35f2c81' AND s.structure_hash = 'seed-test-hsa-04' AND NOT s.edited AND EXISTS (SELECT 1 FROM exam.exam e WHERE e.id = s.exam_id AND e.status = 'DRAFT') AND NOT EXISTS (SELECT 1 FROM exam.exam_version v WHERE v.exam_id = s.exam_id)),
dropped AS (DELETE FROM exam.exam_block_ref r USING upgrading u
    WHERE r.exam_id = u.exam_id AND r.version_no IS NULL RETURNING r.id)
UPDATE exam.exam e SET kind_item_id = '00000000-0000-7000-8200-000000000101', scope = 'PART',
    part_code = 'SCIENCE',
    subject_item_id = NULL,
    template_code = 'HSA_PART_SCIENCE',
    structure_year = 2026, matrix_year = 2026,
    years_confirmed = true,
    timing = 'PER_PART', duration_minutes = 60,
    max_score = 50,
    reference_max = NULL,
    practice_scoring = 'RAW',
    question_count = 50, has_essay = false,
    has_english_option = false, combination_count = 0,
    check_status = CASE WHEN e.check_status = 'UNCHECKED' THEN 'UNCHECKED' ELSE 'NEEDS_RECHECK' END,
    revision = e.revision + 1, updated_at = now()
FROM upgrading u WHERE e.id = u.exam_id;

