    matrix_year, years_confirmed, timing, duration_minutes, max_score, reference_max,
    practice_scoring, status, check_status, question_count, has_essay,
    has_english_option, combination_count, has_unpublished_changes, revision) VALUES
  ('be11dde0-946e-5f37-846c-684f033a779c','TEST-QDA-01','test-qda-01','TEST · QDA toàn bài','Đề test giả định dựng từ mẫu QDA_FULL (UNI-2701).',NULL,'00000000-0000-7000-8200-000000000102','FULL',NULL,NULL,'QDA_FULL',2026,2026,true,'PER_PART',195,150,NULL,'RAW','DRAFT','UNCHECKED',150,false,true,5,false,0)
ON CONFLICT (id) DO NOTHING;

WITH upgrading AS (SELECT s.exam_id FROM exam.exam_structure s
    WHERE s.exam_id = 'be11dde0-946e-5f37-846c-684f033a779c' AND s.structure_hash = 'seed-test-qda-01' AND NOT s.edited AND EXISTS (SELECT 1 FROM exam.exam e WHERE e.id = s.exam_id AND e.status = 'DRAFT') AND NOT EXISTS (SELECT 1 FROM exam.exam_version v WHERE v.exam_id = s.exam_id)),
dropped AS (DELETE FROM exam.exam_block_ref r USING upgrading u
    WHERE r.exam_id = u.exam_id AND r.version_no IS NULL RETURNING r.id)
UPDATE exam.exam e SET kind_item_id = '00000000-0000-7000-8200-000000000102', scope = 'FULL',
    part_code = NULL,
    subject_item_id = NULL,
    template_code = 'QDA_FULL',
    structure_year = 2026, matrix_year = 2026,
    years_confirmed = true,
    timing = 'PER_PART', duration_minutes = 195,
    max_score = 150,
    reference_max = NULL,
    practice_scoring = 'RAW',
    question_count = 150, has_essay = false,
    has_english_option = true, combination_count = 5,
    check_status = CASE WHEN e.check_status = 'UNCHECKED' THEN 'UNCHECKED' ELSE 'NEEDS_RECHECK' END,
    revision = e.revision + 1, updated_at = now()
FROM upgrading u WHERE e.id = u.exam_id;

