WITH upgrading AS (SELECT s.exam_id FROM exam.exam_structure s
    WHERE s.exam_id = 'f2294ef4-bfc7-5ba6-ae45-5b6b67e4d132' AND s.structure_hash = 'seed-test-bca-01' AND NOT s.edited AND EXISTS (SELECT 1 FROM exam.exam e WHERE e.id = s.exam_id AND e.status = 'DRAFT') AND NOT EXISTS (SELECT 1 FROM exam.exam_version v WHERE v.exam_id = s.exam_id)),
dropped AS (DELETE FROM exam.exam_block_ref r USING upgrading u
    WHERE r.exam_id = u.exam_id AND r.version_no IS NULL RETURNING r.id)
UPDATE exam.exam e SET kind_item_id = '00000000-0000-7000-8400-000000000103', scope = 'FULL',
    part_code = NULL,
    subject_item_id = NULL,
    template_code = 'BCA_FULL',
    structure_year = 2026, matrix_year = 2026,
    years_confirmed = true,
    timing = 'SHARED', duration_minutes = 180,
    max_score = 100,
    reference_max = NULL,
    practice_scoring = 'RAW',
    question_count = 81, has_essay = true,
    has_english_option = true, combination_count = 4,
    check_status = CASE WHEN e.check_status = 'UNCHECKED' THEN 'UNCHECKED' ELSE 'NEEDS_RECHECK' END,
    revision = e.revision + 1, updated_at = now()
FROM upgrading u WHERE e.id = u.exam_id;

