WITH upgrading AS (SELECT s.exam_id FROM exam.exam_structure s
    WHERE s.exam_id = '9216dd1b-b6fd-54b8-974e-11479d8467ba' AND s.structure_hash = 'seed-test-err-02' AND NOT s.edited AND EXISTS (SELECT 1 FROM exam.exam e WHERE e.id = s.exam_id AND e.status = 'DRAFT') AND NOT EXISTS (SELECT 1 FROM exam.exam_version v WHERE v.exam_id = s.exam_id)),
