WITH upgrading AS (SELECT s.exam_id FROM exam.exam_structure s
    WHERE s.exam_id = '781b5101-69de-5020-91c1-9c4474a18401' AND s.structure_hash = 'seed-test-err-11' AND NOT s.edited AND EXISTS (SELECT 1 FROM exam.exam e WHERE e.id = s.exam_id AND e.status = 'DRAFT') AND NOT EXISTS (SELECT 1 FROM exam.exam_version v WHERE v.exam_id = s.exam_id)),
dropped AS (DELETE FROM exam.exam_block_ref r USING upgrading u
    WHERE r.exam_id = u.exam_id AND r.version_no IS NULL RETURNING r.id)
UPDATE exam.exam e SET kind_item_id = '00000000-0000-7000-8400-000000000107', scope = 'SUBJECT',
    part_code = NULL,
    subject_item_id = '00000000-0000-7000-8200-000000000201',
    template_code = 'THPTQG_MATH_2025',
    structure_year = 2025, matrix_year = 2025,
    years_confirmed = true,
    timing = 'SHARED', duration_minutes = 90,
    max_score = 10,
    reference_max = NULL,
    practice_scoring = 'RAW',
    question_count = 22, has_essay = false,
    has_english_option = false, combination_count = 0,
    check_status = CASE WHEN e.check_status = 'UNCHECKED' THEN 'UNCHECKED' ELSE 'NEEDS_RECHECK' END,
    revision = e.revision + 1, updated_at = now()
FROM upgrading u WHERE e.id = u.exam_id;

